fn main() {
    // (has_link, all_caps) -> spam? 1.0 : 0.0
    let data = [
        (1.0, 1.0, 1.0), // link + caps = spam
        (1.0, 0.0, 1.0), // link        = spam
        (0.0, 0.0, 0.0), // plain       = ham
    ];

    let (mut w1, mut w2, mut b) = (0.0, 0.0, 0.0);
    let lr = 0.1;

    for _ in 0..50 {
        for (x1, x2, target) in data {
            let sum = w1 * x1 + w2 * x2 + b;
            let out = if sum > 0.0 { 1.0 } else { 0.0 };
            let err = target - out;
            w1 += lr * err * x1;
            w2 += lr * err * x2;
            b += lr * err;
