    next_id: u64,
}

impl Shortener {
    fn new() -> Self {
        Shortener { to_url: HashMap::new(), next_id: 0 }
    }

    fn shorten(&mut self, url: &str) -> String {
        let code = format!("c{}", self.next_id);
        self.next_id += 1;
        self.to_url.insert(code.clone(), url.to_string());
        code
    }

